package reference_test

import (
	"context"
	"testing"

	"github.com/AkashJam/ticker/internal/change"
	"github.com/AkashJam/ticker/internal/ecb"
	"github.com/AkashJam/ticker/internal/fred"
	"github.com/AkashJam/ticker/internal/reference"
)

// The embedded snapshots are generated by `ticker fred --out` and
// `ticker ecb --out`, never typed. This is an external test package because
// fred and ecb import reference.

type countryRows struct {
	Rows []struct {
		Code     string  `json:"code"`
		Currency *string `json:"currency"`
	} `json:"rows"`
}

func load(t *testing.T) (countryRows, fred.Dataset, ecb.Dataset) {
	t.Helper()
	var c countryRows
	var f fred.Dataset
	var e ecb.Dataset
	s := reference.New(nil, reference.Embedded(), nil)
	for name, v := range map[string]any{"countries": &c, "fred": &f, "ecb": &e} {
		if src, err := s.Get(context.Background(), name, v); err != nil || src != reference.SourceEmbedded {
			t.Fatalf("%s: src=%q err=%v", name, src, err)
		}
	}
	return c, f, e
}

// Phase 10 gate: every value carries source and as-of, and the index measures
// are stored as series from January 2010, never as a level the page could use.
func TestEmbeddedFredSnapshot(t *testing.T) {
	c, f, _ := load(t)
	if f.GeneratedAt == "" || len(f.Rows) != len(c.Rows) {
		t.Fatalf("generatedAt=%q rows=%d, countries=%d", f.GeneratedAt, len(f.Rows), len(c.Rows))
	}
	for _, r := range c.Rows {
		row, ok := f.Rows[r.Code]
		if !ok {
			t.Errorf("no row for %s", r.Code)
			continue
		}
		for name, m := range map[string]struct {
			m    fred.Measure
			step int
		}{"shares": {row.Shares, 1}, "housing": {row.Housing, 3}} {
			if m.m.Source == "" || m.m.AsOf == "" || m.m.AsOf != m.m.Series.AsOf() {
				t.Errorf("%s %s: source=%q asOf=%q (series says %q)", r.Code, name, m.m.Source, m.m.AsOf, m.m.Series.AsOf())
			}
			if err := m.m.Series.Validate(); err != nil || m.m.Series.Start != "2010-01" || m.m.Series.Step != m.step {
				t.Errorf("%s %s: series %s step %d, err %v", r.Code, name, m.m.Series.Start, m.m.Series.Step, err)
			}
		}
	}
}

func TestEmbeddedECBSnapshot(t *testing.T) {
	c, _, e := load(t)
	if e.GeneratedAt == "" || e.AsOf == "" || e.Base != "EUR" {
		t.Fatalf("generatedAt=%q asOf=%q base=%q", e.GeneratedAt, e.AsOf, e.Base)
	}
	want := map[string]bool{}
	for _, r := range c.Rows {
		if r.Currency != nil {
			want[*r.Currency] = true
		}
	}
	if len(e.Currencies) != len(want) {
		t.Errorf("ecb.json has %d currencies, countries.json needs %d", len(e.Currencies), len(want))
	}
	if _, ok := e.Currencies["EUR"]; ok {
		t.Error("the euro has no rate against itself and must not appear")
	}
	for code := range want {
		cur, ok := e.Currencies[code]
		if !ok {
			t.Errorf("no entry for %s", code)
			continue
		}
		if cur.Source == "" || cur.AsOf == "" {
			t.Errorf("%s: source=%q asOf=%q", code, cur.Source, cur.AsOf)
		}
		if cur.Series == nil {
			t.Errorf("%s: no series (reason %q)", code, cur.Reason)
			continue
		}
		// The ECB published no shekel for 2010, so Israel's series starts at its
		// first full month and a window needing 2010 is not served for it.
		start := "2010-01"
		if code == "ILS" {
			start = "2011-02"
		}
		if err := cur.Series.Validate(); err != nil || cur.Series.Start != start || cur.Series.Step != 1 || cur.AsOf != cur.Series.AsOf() {
			t.Errorf("%s: series %s step %d asOf %q, err %v (want start %s)", code, cur.Series.Start, cur.Series.Step, cur.AsOf, err, start)
		}
		if (code == "CLP") != (cur.Derived == "via USD") {
			t.Errorf("%s: derived=%q; only Chile is derived via the dollar", code, cur.Derived)
		}
		if code != "CLP" && len(cur.AnnualAverage) == 0 {
			t.Errorf("%s: no annual averages", code)
		}
	}
	if _, ok := e.Currencies["USD"].AnnualAverage["2023"]; !ok {
		t.Error("USD has no 2023 average; step 4 converts World Bank US$ at the same year's rate")
	}
}

// portfolio.md §8 gives Italy's real values cut at 2024, and bearing.md the
// other countries'. If the pipeline, the helper or the snapshots drift, this
// is where it shows.
func TestSnapshotsReproduceThePublishedFigures(t *testing.T) {
	_, f, e := load(t)
	near := func(name string, got *float64, want, tol float64) {
		t.Helper()
		if got == nil {
			t.Errorf("%s = nil, want %v", name, want)
			return
		}
		if d := *got - want; d > tol || d < -tol {
			t.Errorf("%s = %v, want %v", name, *got, want)
		}
	}
	it := f.Rows["IT"]
	for _, w := range []struct {
		start           int
		shares, housing float64
	}{{2021, 47.5, -4.1}, {2016, 75.5, -6.6}, {2010, 69.8, -26.0}} {
		near("IT shares", it.Shares.Series.Window(w.start, 2024), w.shares, 0.05)
		near("IT housing", it.Housing.Series.Window(w.start, 2024), w.housing, 0.05)
	}
	years := it.Shares.Series.Years(change.FirstYear, 2024)
	near("IT shares 2010", ptr(years["2010"]), -5.4, 0.05)
	near("IT shares 2011", ptr(years["2011"]), -24.4, 0.05)

	near("IN shares 2010-24", f.Rows["IN"].Shares.Series.Window(2010, 2024), 364, 1)
	near("IN housing 2010-24", f.Rows["IN"].Housing.Series.Window(2010, 2024), 64, 1)
	near("JP shares 2010-24", f.Rows["JP"].Shares.Series.Window(2010, 2024), 193, 1)
	near("US housing 2010-24", f.Rows["US"].Housing.Series.Window(2010, 2024), 59, 1)

	// Chile over 2010-24 is about -31%, derived through the dollar.
	clp := e.Currencies["CLP"].Series
	if clp == nil {
		t.Fatal("Chile has no series")
	}
	ils := e.Currencies["ILS"].Series
	if ils == nil || ils.Invert().Window(2010, 2024) != nil || ils.Invert().Window(2016, 2024) == nil {
		t.Error("Israel: the 2010 window must not be served and the 2016 window must be")
	}
	near("CLP 2010-24", clp.Invert().Window(2010, 2024), -31, 1.5)
}

func ptr(v float64) *float64 { return &v }
